import express from 'express';
import { PasswordController } from '../controllers/password.controller.js';
import { requireAuth } from '../middleware/auth.js';
import { rateLimit, validateEmail, validatePasswordReset, validatePasswordChange } from '../middleware/validation.js';
const router = express.Router();
router.post('/request-reset', validateEmail, rateLimit(3, 300000), PasswordController.requestReset);
router.get('/verify-token/:token', rateLimit(10, 300000), PasswordController.verifyResetToken);
router.post('/reset', validatePasswordReset, rateLimit(5, 300000), PasswordController.resetPassword);
router.post('/change', requireAuth, validatePasswordChange, rateLimit(5, 300000), PasswordController.changePassword);
router.get('/info', requireAuth, PasswordController.getPasswordInfo);
router.get('/email-status', PasswordController.getEmailServiceStatus);
export default router;
